INSERT INTO characters (id, name, set, description, energy, combat, brute_force, intelligence, image_path, reverse_image_path, threat_level, special_abilities, set_number, set_number_foil, is_foil, rarity, created_at, updated_at)
SELECT gen_random_uuid(), i.name, i.set, i.description, i.energy::integer, i.combat::integer, i.brute_force::integer, i.intelligence::integer, i.image_path, i.reverse_image_path, i.threat_level::integer, i.special_abilities, i.set_number, i.set_number_foil, i.is_foil, i.rarity, NOW(), NOW()
FROM incoming i
WHERE NOT EXISTS (
  SELECT 1 FROM characters existing
  WHERE existing.set = i.set
    AND existing.set_number = i.set_number
    AND existing.is_foil = i.is_foil
);


WITH incoming (name, character_name, set, card_effect, image_path, one_per_deck, cataclysm, ambush, assist, icons, value, set_number, set_number_foil, banned, is_foil, icon_offensive_swords, icon_defensive_shield, icon_remainder_of_battle, icon_remainder_of_game, icon_attached_paperclip, icon_astral_plane, icon_first_action_only, rarity) AS (
VALUES
  ('Extreme Measures', 'Invincible', 'SKY', 'Acts as a level 10 Brute Force attack. Invincible is -2 to all actions while this card is a hit from current battle on a character.', 'sky/specials/002_extreme_measures.png', TRUE, FALSE, FALSE, FALSE, ARRAY[]::text[], 10, '002', NULL, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'Uncommon'),
  ('I am Invincible', 'Invincible', 'SKY', 'For remainder of battle, all attacks on Invincible''s team are shifted to Invincible. At the End of Battle Phase, once missions have been moved, all hits from current battle are removed and are not added to Invincible''s permanent record.', 'sky/specials/003_i_am_invincible.png', TRUE, FALSE, FALSE, FALSE, ARRAY[]::text[], NULL, '003', NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, 'Common'),
  ('Brutal Fighter', 'Invincible', 'SKY', 'Acts as a level 7 Any-Power attack.', 'sky/specials/004_brutal_fighter.png', FALSE, FALSE, FALSE, FALSE, ARRAY['Any-Power']::text[], 7, '004', NULL, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'Common'),
  ('Combat Training', 'Invincible', 'SKY', 'Acts as a level 5 Combat defense, +1 for each hit on Invincible''s current battle and permanent record. May defend Invincible or teammate.', 'sky/specials/005_combat_training.png', FALSE, FALSE, FALSE, FALSE, ARRAY[]::text[], 5, '005', NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'Common'),
  ('Sucker Punch', 'Invincible', 'SKY', 'Acts as a level 3 MultiPower attack. If successful, and target has no hits on their current battle and permanent record, target must discard 1 card placed to them or in hand.', 'sky/specials/006_sucker_punch.png', FALSE, FALSE, FALSE, FALSE, ARRAY['Energy']::text[], 3, '006', NULL, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'Common'),
  ('Viltrumite Legacy', 'Invincible', 'SKY', 'Invincible is +3 to Venture Total this battle. Remove 1 hit from Invincible''s permanent record.', 'sky/specials/007_viltrumite_legacy.png', FALSE, FALSE, FALSE, FALSE, ARRAY[]::text[], NULL, '007', NULL, FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'Common'),
  ('I''m Here to Help', 'Omni-Man', 'SKY', 'Omni-Man or teammate may avoid 1 attack. Opponent''s turn immediately ends.', 'sky/specials/009_i_m_here_to_help.png', TRUE, FALSE, FALSE, FALSE, ARRAY[]::text[], NULL, '009', NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'Common'),
  ('Brutal Efficiency', 'Omni-Man', 'SKY', 'Acts as a level 6 Combat attack. If successful, target character may not use cards with a Combat icon for remainder of battle.', 'sky/specials/010_brutal_efficiency.png', FALSE, FALSE, FALSE, FALSE, ARRAY['Combat']::text[], 6, '010', NULL, FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'Common'),
