INSERT INTO special_cards (id, name, character_name, set, card_effect, image_path, one_per_deck, cataclysm, ambush, assist, icons, value, set_number, set_number_foil, banned, is_foil, icon_offensive_swords, icon_defensive_shield, icon_remainder_of_battle, icon_remainder_of_game, icon_attached_paperclip, icon_astral_plane, icon_first_action_only, rarity, created_at, updated_at)
SELECT gen_random_uuid(), i.name, i.character_name, i.set, i.card_effect, i.image_path, i.one_per_deck, i.cataclysm, i.ambush, i.assist, i.icons, i.value::integer, i.set_number, i.set_number_foil, i.banned, i.is_foil, i.icon_offensive_swords, i.icon_defensive_shield, i.icon_remainder_of_battle, i.icon_remainder_of_game, i.icon_attached_paperclip, i.icon_astral_plane, i.icon_first_action_only, i.rarity, NOW(), NOW()
FROM incoming i
WHERE NOT EXISTS (
  SELECT 1 FROM special_cards existing
  WHERE existing.set = i.set
    AND existing.set_number = i.set_number
    AND existing.is_foil = i.is_foil
);


