INSERT INTO missions (id, name, set, mission_description, image_path, mission_set, set_number, set_number_foil, set_number_int, is_foil, rarity, created_at, updated_at)
SELECT gen_random_uuid(), i.name, i.set, i.mission_description, i.image_path, i.mission_set, i.set_number, i.set_number_foil, i.set_number_int::integer, i.is_foil, i.rarity, NOW(), NOW()
