WITH incoming (name, set, event_description, image_path, one_per_deck, mission_set, game_effect, flavor_text, set_number, set_number_foil, is_foil, rarity) AS (
VALUES
  ('The New Guardians', 'SKY', 'The New Guardians event card', 'sky/events/402_the_new_guardians.png', TRUE, 'Who Killed the Guardians of the Globe?', 'Ally cards can be played by any character, ignoring requirements to play, but with normal follow-up requirements.', '', '402', NULL, FALSE, 'Common'),
  ('Daily Security Briefing: Calm Before the Storm', 'SKY', 'Daily Security Briefing: Calm Before the Storm event card', 'sky/events/403_daily_security_briefing_calm_before_the_storm.png', TRUE, 'Who Killed the Guardians of the Globe?', 'Nolan is off. Seems indifferent to the Guardians'' deaths. And some of them were his friends. Every instinct I have is screaming this situation isn''t right, but I need Nolan operational. If we''re facing a new enemy of this scale, we can''t afford to have our strongest piece off the board. And if it''s not a new enemy…Well, let''s just hope I''m wrong. // END BRIEFING // Each character may remove 1 hit from their permanent record.', '', '403', NULL, FALSE, 'Common'),
  ('The World Mourns', 'SKY', 'The World Mourns event card', 'sky/events/404_the_world_mourns.png', TRUE, 'Who Killed the Guardians of the Globe?', 'Public funeral and global grief. Nolan plays the grieving comrade perfectly—people eat it up. No one suspects. Not yet. Still doesn''t explain how someone took out the Guardians and Omni-Man. Darkblood sticking his horns where they don''t belong. He''ll dig in too far. He always does. May have to deal with him sooner than later.
// END BRIEFING //
WHO KILLED THE GUARDIANS OF THE GLOBE?
Hits with an Energy icon do not count to the Venture Total this battle.', '', '404', NULL, FALSE, 'Common'),
  ('Guardians Wiped Out', 'SKY', 'Guardians Wiped Out event card', 'sky/events/405_guardians_wiped_out.png', TRUE, 'Who Killed the Guardians of the Globe?', 'Situation critical. Full team of The Guardians of the Globe eliminated. Whoever pulled this off either knew their weaknesses... or didn''t care. No known assailant but God help us if it''s who I suspect. We''re blind, exposed, and vulnerable. Need to move fast. No cavalry coming. // END BRIEFING // WHO KILLED THE GUARDIANS OF THE GLOBE? No Teamwork Universe cards may be played this battle.', '', '405', NULL, FALSE, 'Uncommon'),
  ('Traitor Revealed', 'SKY', 'Traitor Revealed event card', 'sky/events/406_traitor_revealed.png', TRUE, 'Who Killed the Guardians of the Globe?', 'Attacks this battle ignore any of Opponent''s Special cards in play with the text "may not attack," and "may not be attacked."', '', '406', NULL, FALSE, 'Uncommon'),
  ('We Choose How To Fight', 'SKY', 'We Choose How To Fight event card', 'sky/events/414_we_choose_how_to_fight.png', TRUE, 'We Are Negan', 'They''ve got the numbers—we don''t. A head-on fight is suicide. I read about a Spartan king who held off a hundred thousand with just 300 men. They used the ground. That''s what we''ll do. Hit first, hit loud—draw a herd in behind us. Let the dead finish the job.

Hits with a Combat icon do not count to the Venture Total this battle.', '', '414', NULL, FALSE, 'Common'),
  ('Bleeding Out', 'SKY', 'Bleeding Out event card', 'sky/events/415_bleeding_out.png', TRUE, 'We Are Negan', 'Every Savior attack costs us. Even when we win, we lose—good people. Supplies can be replaced. People can''t. And we''re bleeding out. The Hilltop and Kingdom are cut off. Roads are crawling with threats. We need to regroup, strike hard, and finish this war—before it finishes all of us.

No Ally cards may be played this battle.', '', '415', NULL, FALSE, 'Common'),
  ('Going All In', 'SKY', 'Going All In event card', 'sky/events/416_going_all_in.png', TRUE, 'We Are Negan', 'Each player must venture at least 2 Mission cards this battle. Ignore this Event if both players cannot venture at least 2 Mission cards.', '', '416', NULL, FALSE, 'Common'),
  ('Is that a bite?', 'SKY', 'Is that a bite? event card', 'sky/events/417_is_that_a_bite.png', TRUE, 'We Are Negan', 'No current battle or permanent record hits may be removed with a Special card this battle.', '', '417', NULL, FALSE, 'Uncommon'),
